import sys

def min_distance_to_zero(n, arr):
    stack = []
    result = [float('inf')] * n

    # First pass: from left to right
    for i in range(n):
        while stack and arr[i] != 0:
            if abs(i - stack[-1]) < result[stack[-1]]:
                result[stack.pop()] = abs(i - stack[-1])
            else:
                break
        stack.append(i)

    # Second pass: from right to left
    stack.clear()
    for i in range(n-1, -1, -1):
        while stack and arr[i] != 0:
            if abs(i - stack[-1]) < result[stack[-1]]:
                result[stack.pop()] = abs(i - stack[-1])
            else:
                break
        stack.append(i)

    return result

